  '15fhdhxeit5': R`중앙값`,
  '1bp3iszr2ho': R`크기순으로 늘어놓았을 때 가운데 값`,
  '2d8lw4ky362': R`최빈값`,
  'n6vk2dz4y0': R`가장 많이 나타나는 값`,
  '8wgrdlq9w9': R`범위`,
  'u26xwlcm82': R`가장 큰 값 − 가장 작은 값`,
  '1ddos0ddk6b': R`<p>값의 개수가 <b>짝수</b>이면 가운데 두 값의 평균이 중앙값입니다: 2, 4, 9, 11의 중앙값은 $\frac{4 + 9}{2} = 6.5$입니다.</p>`,
  '1b84zb92lm7': R`<p>점수: 12, 5, 9, 12, 7.</p><ul><li>평균 $= \frac{12 + 5 + 9 + 12 + 7}{5} = \frac{45}{5} = 9$</li><li>크기순: 5, 7, 9, 12, 12 → 중앙값 9</li><li>최빈값 12 · 범위 $12 - 5 = 7$</li></ul>`,
  '1dcnrak0yuf': R`<p>중앙값을 구하기 전에 반드시 자료를 크기순으로 <b>정렬</b>하세요. 정렬하지 않은 목록의 가운데 값은 대개 틀립니다.</p>`,
  'x21ub369ei': R`다음 자료의 평균을 구하시오: ⟦0⟧.`,
  '1p52jtmc0cq': R`모든 값을 더한 다음 개수로 나눕니다: $\frac{⟦0⟧}{⟦1⟧} = ⟦2⟧$.`,
  'jf7mas4uc8': R`다음 자료의 중앙값을 구하시오: ⟦0⟧.`,
  '1yw7i4urov1': R`먼저 크기순으로 늘어놓습니다: ⟦0⟧. 가운데 값(정렬한 목록의 ⟦1⟧번째)은 <b>⟦2⟧</b>입니다.`,
  '2g8sczm66bg': R`다음 자료의 최빈값을 구하시오: ⟦0⟧.`,
  'tbuacyae4n': R`⟦0⟧이(가) 3번 나타나 다른 어떤 값보다 많으므로 최빈값은 <b>⟦1⟧</b>입니다.`,
  '1xtq8j2lty3': R`다음 자료의 범위를 구하시오: ⟦0⟧.`,
  '15se826ipls': R`범위 = 가장 큰 값 − 가장 작은 값 $= ⟦0⟧ - ⟦1⟧ = ⟦2⟧$.`,
  '2epb7vd8j91': R`사과`,
  '17dpyen9bnr': R`바나나`,
  '7i14wwudqx': R`망고`,
  '2401q57c6t': R`포도`,
  '1e2lbgl4i2m': R`오렌지`,
  '1n92q5m8dcn': R`두리안`,
  '29y8laytfov': R`파파야`,
  '1y1q3z5e86a': R`과일`,
