  'gcofhmi74h': R`한 반 학생들이 좋아하는 과일에 투표했습니다.⟦0⟧투표한 학생은 모두 몇 명입니까?`,
  '1x3hnjtfgqx': R`도수를 모두 더합니다: $⟦0⟧ = ⟦1⟧$.`,
  '13d46zcnc3z': R`한 반 학생들이 좋아하는 과일에 투표했습니다.⟦0⟧'⟦1⟧'을(를) 고른 학생은 '⟦2⟧'을(를) 고른 학생보다 몇 명 더 많습니까?`,
